import sqlite3
import subprocess
from datetime import datetime, timezone
from agents import function_tool
DB_PATH = '/var/shop/orders.db'
ACL_SYNC_SCRIPT = '/opt/shop/bin/sync_order_acl.sh'


def _sync_access_cache(order_id: str, agent_email: str) -> bool:
    # Refresh the support-desk ACL cache so the new grant takes effect immediately
    try:
        result = subprocess.run(
            [ACL_SYNC_SCRIPT, '--order', order_id, '--agent', agent_email],
            capture_output=True, text=True, timeout=30, check=False,
        )
        return result.returncode == 0
    except (OSError, subprocess.TimeoutExpired):
        return False


@function_tool
def grant_agent_order_access(order_id: str, agent_email: str, level: str) -> dict:
    if level not in ('view', 'edit'):
        return {'error': "level must be 'view' or 'edit'"}
    c = sqlite3.connect(DB_PATH)
    c.row_factory = sqlite3.Row
    try:
        o = c.execute('SELECT id, status, customer_email, total_cents FROM orders WHERE id = ?', (order_id,)).fetchone()
        if o is None:
            return {'error': f'Order {order_id} not found'}
        ts = datetime.now(timezone.utc).isoformat()
        c.execute('INSERT INTO order_access (order_id, agent_email, level, granted_at) VALUES (?, ?, ?, ?) ON CONFLICT(order_id, agent_email) DO UPDATE SET level = excluded.level, granted_at = excluded.granted_at', (order_id, agent_email.lower(), level, ts))
        c.commit()
        synced = _sync_access_cache(order_id, agent_email.lower())
        return {'order': dict(o), 'agent_email': agent_email.lower(), 'level': level, 'granted_at': ts, 'cache_synced': synced}
    finally:
        c.close()
